#include <iostream>

typedef double FT;
struct Point_2 {
    double x_val, y_val;
    double x() const { return x_val; }
    double y() const { return y_val; }
    Point_2(double x, double y) : x_val(x), y_val(y) {}
};

FT squared_distance(const Point_2& p, const Point_2& q) {
    FT dx = p.x() - q.x();
    FT dy = p.y() - q.y();
    return dx * dx + dy * dy;
}

int main() {
    Point_2 p(0, 0), q(3, 4);
    if (squared_distance(p, q) == 25.0) {
        std::cout << "Success" << std::endl;
    } else {
        std::cout << "Failure" << std::endl;
    }
    return 0;
}

